mapper.update:
update operation_plan
   set status = 'UNLOADING',
       version = version + 1,
       terminal_source = 'MANUAL',
       terminal_reason = #{reason},
       updated_by = #{updatedBy},
       updated_at = #{updatedAt}
 where id = #{id}
   and status = #{status}
   and version = #{version}

mapper.select:
select * from operation_plan where resource_type = 'rule' and resource_id = #{ruleId}
and resource_version = #{ruleVersion}
and status <> 'UNLOADED' order by updated_at desc, id
